presetParts.warp:
shader_body {
//uv1 is rect. screen, center at (0;0)
float2 uv1 = (uv-0.5)*aspect.xy;
float corr = texsize.xy*texsize_noise_hq.zw*2;


//uv2 is derived from uv1: Horizon, Tilt, Movement
//1. shape horizion for small planet look
float2 uv2 = uv1;
uv2.y =   uv1.y - .2*(uv1.x*uv1.x + uv1.y*uv1.y);

//2. Tilt
float2x2 tilt = float2x2(q30,q31,-q31,q30);
uv2 = mul(tilt,uv2);

//3. Coord transform
float y0 = q3 ; //Horizon rel. to  screen
float z0 = .5 ; //  fish eye
float z = 8/abs(uv2.y+ y0); //factor for perspective
float2 rs1 = float2 (uv2.x*z,(uv2.y-1*z0)*z);

//Rotate map into viewing direction
float2x2 dir = float2x2(q24,q25,-q25,q24);
rs1 =  mul(dir,rs1);

//Now move !
rs1 = rs1 - float2 (0,q1);

float yr = (uv2.y +y0);
float mask = saturate (16*yr) ;

float3 sky2 = tex2D(sampler_noise_hq,0.001*rs1*corr);

float gravel =  lum(tex2D(sampler_noise_mq,0.008*rs1*corr));
float lav_mask = (sky2 * q28*(gravel+.0));;

float lava = 0.2+abs (lav_mask-0);
lava = saturate (0.5/(lava+.1)-0.5);
float rock = (lav_mask)/64;

float3 lay1 = saturate(float3 (lava,lava*(lava-0.52)*2,(lava-.94)*8));
lay1 = mask * (lay1 + rock * float3 (.8,1,1));

float3 copy = + GetBlur2(float2(uv_orig.x, uv_orig.y+.00));
ret = lay1 + 0*lerp(copy,lum(copy),0.8)*.5* mask 
+ q22/(.03+abs(yr))*float3(.7,.3,.9);

}

presetParts.comp:
sampler sampler_facade01;

float3 ret1, neu, musl, musr, screen3, pos0, pos1;
float2 pq, pq2;
int mask1, mask2;
float n, dist2;
static const float width =5;
static const float depth =28;
static float3 sxy = float3(q4,q5,q6);
static float3 sxz = float3(q7,q8,q9);
static float3 t = -cross(sxy,sxz);
static float blend = q32;


float2 project (float3 s, float3 pos) {
  float Nenner;  float2x3 ts;
  ts = float2x3(t,-s);
  Nenner = mul(cross(t,s),screen3);
  dist2 = Nenner;
  return (mul(ts,cross(pos,screen3))/Nenner);}

float2 project_gnd (float3 pos) {
  float Nenner;  float2x3 ts;
  ts = float2x3(sxz,-sxy);//auch -t probieren ###
  Nenner = mul(cross(sxz,sxy),screen3);
  return (mul(ts,cross(pos,screen3/48))/Nenner);}

float3 wall (float2 xy) {
  return(-.2+tex2D (sampler_facade01,xy/4).brg);
}

shader_body {
screen3 = float3 ((uv-.5)*aspect.xy,1);//wirkt wie zoom
neu = GetBlur1(uv)/4;

  pq  = project (sxy, float3 (q10,q11,q12)); 
  pq2 = project (sxz, float3 (q10,q11,q12)); 
  mask1 = (pq.x>=0)* (pq.x <=width);
  mask2 = (pq2.x>=0)*(pq2.x <= depth);
  if (mask1) {neu = lerp(neu,wall(pq*mask1),blend);}
  if (mask2) {neu = lerp(neu,wall(pq2*mask2),blend);}

  pq  = project (-sxy, float3 (q13,q14,q15)); 
  pq2 = project (sxz, float3 (q13,q14,q15)); 
  mask1 = (pq.x>=0)* (pq.x <=width);
  mask2 = (pq2.x>=0)*(pq2.x <= depth);
  if (mask1) {neu = lerp(neu,wall(pq*mask1),blend);}
  if (mask2) {neu = lerp(neu,wall(pq2*mask2),blend);}

  pq  = project (sxy, float3 (q16,q17,q18)); 
  pq2 = project (sxz, float3 (q16,q17,q18)); 
  mask1 = (pq.x>=0)* (pq.x <=width) * (dist2 >=0);
  mask2 = (pq2.x>=0)*(pq2.x <= depth)* (dist2 >=0);
  if (mask1) {neu = wall(pq*mask1);}
  if (mask2) {neu = wall(pq2*mask2);}
  musr = (q29%2)/length(abs(frac(pq2/2)-.5))*mask2;
  musr += (q29%2)/length(abs(frac(pq/2)-.5))*mask1;

  pq  = project (-sxy, float3 (q19,q20,q21)); 
  pq2 = project (sxz, float3 (q19,q20,q21)); 
  mask1 = (pq.x>=0)* (pq.x <=width) * (dist2 <=0);
  mask2 = (pq2.x>=0)*(pq2.x <= depth)* (dist2 <=0);
  if (mask1) {neu = wall(pq*mask1);}
  if (mask2) {neu = wall(pq2*mask2);}
  musl = ((q29+1)%2)/length(abs(frac(pq2/2)-.5))*mask2;
  musl += ((q29+1)%2)/length(abs(frac(pq/2)-.5))*mask1;

ret = tex2D (sampler_main,uv+neu/8)
+neu*(1+roam_cos)*saturate(bass_att*.04/length(uv-.5))/2
*(bass_att) + saturate((musl*roam_sin+musr*roam_cos)/16)*mid_att;

}
